function.arguments:
{"command": "cd /workspace && cat > work/build.py <<'EOF'
import json, numpy as np

S = json.load(open('work/samples.json'))
SEMI = {'C':0,'C#':1,'Db':1,'D':2,'D#':3,'Eb':3,'E':4,'F':5,'F#':6,'Gb':6,'G':7,'G#':8,'Ab':8,'A':9,'A#':10,'Bb':10,'B':11}
def N(name):
    # e.g. 'A4' -> XM note number (C-0 = 1); 'G#5'
    if name[1] in '#b':
        p, o = name[:2], int(name[2:])
    else:
        p, o = name[0], int(name[1:])
    return o*12 + SEMI[p] + 1

def VB(v):  # velocity 0..1 -> volume column byte (empirical: level = (byte-16)/48)
    return 16 + int(round(max(0,min(1,v))*48))

# channels
KICK,SNRE,HATS,BASS,ARP,LEAD,STAB,FX = range(8)
INS = dict(kick=1,snare=2,chat=3,ohat=4,bass=5,arp=6,lead=7,stabm=8,stabM=9,fxdown=10,fxrise=11,clap=12)

cells = []   # (pattern,row,ch,note,ins,vol,fx,fxp)
def C(p,r,ch,note=None,ins=None,vol=None,fx=None,fxp=None):
    cells.append((p,r,ch,note,ins,vol,fx,fxp))

PROG = {
 0: [('A','m'),('A','m'),('F','M'),('G','M')],
 1: [('A','m'),('A','m'),('F','M'),('G','M')],
 2: [('A','m'),('F','M'),('C','M'),('G','M')],
 3: [('A','m'),('F','M'),('D','m'),('E','M')],
 4: [('D','m'),('A','m'),('F','M'),('E','M')],
 5: [('A','m'),('F','M'),('C','M'),('G','M')],
 6: [('A','m'),('F','M'),('D','m'),('E','M')],
 7: [('A','m'),('A','m'),('F','M'),('G','M')],
}
CHT = {'m':[0,3,7], 'M':[0,4,7]}

# ---------- groove generators ----------
def bass_bar(p, bar, root, ghost=False):
    g = [(0,0,.95),(3,0,.70),(6,12,.78),(8,0,.90),(11,12,.70),(14,7,.82)]
    if ghost: g += [(2,0,.38),(10,0,.42),(13,0,.38)]
    for pos,off,v in g:
        C(p, bar*16+pos, BASS, root+off, INS['bass'], VB(v))

def kick_bar(p, bar, pat=(0,4,8,12), v=.92):
    for pos in pat: C(p, bar*16+pos, KICK, 49, INS['kick'], VB(v))

def snare_bar(p, bar, pat=(4,12), v=.78, clap=0.0):
    for pos in pat:
        C(p, bar*16+pos, SNRE, 61, INS['snare'], VB(v))
        if clap>0: C(p, bar*16+pos, FX, 61, INS['clap'], VB(clap))

def hats_bar(p, bar, mode='main'):
    if mode=='main':
        for pos in range(16):
            v = .50 if pos%4==0 else (.30 if pos%2==0 else .20)
            C(p, bar*16+pos, HATS, 73, INS['chat'], VB(v))
        C(p, bar*16+14, HATS, 73, INS['ohat'], VB(.42))
    elif mode=='8ths':
        for pos in range(0,16,2):
            v = .42 if pos%4==0 else .26
            C(p, bar*16+pos, HATS, 73, INS['chat'], VB(v))
    elif mode=='break':
        for pos in (0,4,8,12):
            C(p, bar*16+pos, HATS, 73, INS['chat'], VB(.28))

def arp_bar(p, bar, rootsemi, qual, mode='main', base_oct=4):
    tones = CHT[qual]
    pool = [0, tones[1], tones[2], 12, 12+tones[1], 12+tones[2]]
    if mode=='main':
        seq = [0,1,2,3,4,5,4,3, 2,1,2,3,4,3,2,1]
        for pos,idx in enumerate(seq):
            v = .52 if pos%4==0 else .33
            C(p, bar*16+pos, ARP, rootsemi+pool[idx], INS['arp'], VB(v))
    elif mode=='8ths':
        seq = [0,2,4,3, 0,2,4,5]
        for i,idx in enumerate(seq):
            C(p, bar*16+i*2, ARP, rootsemi+pool[idx], INS['arp'], VB(.40))

def stab_hit(p, bar, pos, rootsemi, qual, v=.5):
    ins = INS['stabm'] if qual=='m' else INS['stabM']
    C(p, bar*16+pos, STAB, rootsemi, ins, VB(v))

def root_note(name, oct_): return N(name+str(oct_))

# lead melodies: dict pattern -> list of (bar,pos,note,vol)
LEAD = {
 1: [(3,8,'A4',.66),(3,10,'C5',.66),(3,12,'D5',.70),(3,14,'E5',.74)],
 2: [(0,0,'A5',.88),(0,2,'A5',.72),(0,4,'G5',.74),(0,6,'E5',.72),(0,8,'A5',.86),(0,12,'G5',.70),(0,14,'E5',.68),
     (1,0,'F5',.86),(1,2,'F5',.70),(1,4,'E5',.72),(1,6,'C5',.70),(1,8,'F5',.84),(1,12,'E5',.68),(1,14,'D5',.66),
     (2,0,'E5',.86),(2,2,'E5',.70),(2,4,'D5',.72),(2,6,'C5',.70),(2,8,'E5',.84),(2,12,'D5',.68),(2,14,'C5',.66),
     (3,0,'D5',.86),(3,2,'D5',.70),(3,4,'E5',.74),(3,6,'G5',.76),(3,8,'B5',.88),(3,12,'A5',.72),(3,14,'G5',.70)],
 3: [(0,0,'A5',.88),(0,2,'A5',.72),(0,4,'C6',.80),(0,6,'B5',.74),(0,8,'A5',.86),(0,12,'G5',.70),(0,14,'E5',.68),
     (1,0,'A5',.86),(1,2,'A5',.70),(1,4,'G5',.72),(1,6,'F5',.70),(1,8,'A5',.84),(1,12,'C6',.78),(1,14,'A5',.70),
     (2,0,'F5',.84),(2,2,'F5',.70),(2,4,'E5',.72),(2,6,'D5',.70),(2,8,'F5',.82),(2,12,'A5',.76),(2,14,'G5',.70),
     (3,0,'E5',.86),(3,2,'E5',.72),(3,4,'G#5',.80),(3,6,'B5',.78),(3,8,'G#5',.88)],
 5: [(0,0,'A5',.90),(0,2,'A5',.74),(0,4,'C6',.80),(0,6,'A5',.72),(0,8,'G5',.80),(0,10,'E5',.70),(0,12,'D5',.70),(0,14,'E5',.74),
     (1,0,'F5',.86),(1,2,'F5',.72),(1,4,'A5',.76),(1,6,'C6',.80),(1,8,'A5',.86),(1,12,'G5',.70),(1,14,'F5',.68),
     (2,0,'G5',.86),(2,2,'G5',.72),(2,4,'E5',.72),(2,6,'C5',.70),(2,8,'D5',.74),(2,10,'E5',.72),(2,12,'G5',.78),(2,14,'A5',.80),
     (3,0,'B5',.88),(3,2,'B5',.74),(3,4,'G5',.72),(3,6,'D5',.70),(3,8,'B5',.88),(3,12,'A5',.72),(3,14,'B5',.74)],
 6: [(0,0,'E6',.92),(0,4,'C6',.78),(0,6,'B5',.74),(0,8,'A5',.86),(0,12,'G5',.70),(0,14,'A5',.72),
     (1,0,'C6',.90),(1,4,'A5',.76),(1,6,'G5',.72),(1,8,'F5',.84),(1,12,'G5',.70),(1,14,'A5',.72),
     (2,0,'F5',.80),(2,2,'G5',.72),(2,4,'A5',.76),(2,6,'C6',.80),(2,8,'D6',.92),(2,12,'C6',.76),(2,14,'A5',.72),
     (3,0,'G#5',.88),(3,4,'A5',.78),(3,6,'B5',.80),(3,8,'G#5',.90),(3,12,'E5',.76),(3,14,'B4',.74)],
}

def lead_pat(p):
    for bar,pos,note,v in LEAD.get(p,[]):
        C(p, bar*16+pos, LEAD, N(note), INS['lead'], VB(v))
        # echo on FX-ish free channel: use channel 7? FX used for clap; echo goes to STAB? no.
        # echo handled separately on channel FX when free? use dedicated echo on ch7 only when no clap conflict: keep echo off in P2..; use ch 7 = FX; conflicts rare (clap at 4,12). Echo delayed +3 rows could collide; choose delay 3 and skip colliding rows.

ECHO_PAT = {2,3,5,6}
def echo_pat(p):
    busy = set()
    for (pp,r,ch,*_ ) in cells:
        if pp==p and ch==FX: busy.add(r)
    for bar,pos,note,v in LEAD.get(p,[]):
        r = bar*16+pos+3
        if r>63 or r in busy: continue
        C(p, r, FX, N(note), INS['lead'], VB(v*.32))

# ---------------- build sections ----------------
for p in range(8):
    for bar,(rt,qual) in enumerate(PROG[p]):
        rsemi_bass = root_note(rt,2)
        rsemi_arp  = root_note(rt,4)
        rsemi_stab = root_note(rt,3)
        if p==0:   # intro
            kick_bar(p,bar); bass_bar(p,bar,rsemi_bass)
            arp_bar(p,bar,rsemi_arp,qual,'main')
            hats_bar(p,bar,'8ths')
            if bar==3: snare_bar(p,bar,v=.7)
        elif p==1: # intro 2
            kick_bar(p,bar); bass_bar(p,bar,rsemi_bass,ghost=(bar%2==1))
            arp_bar(p,bar,rsemi_arp,qual,'main')
            hats_bar(p,bar,'main')
            snare_bar(p,bar,v=.72,clap=.25)
            if bar in (1,3):
                stab_hit(p,bar,2,rsemi_stab,qual,.42); stab_hit(p,bar,10,rsemi_stab,qual,.38)
        elif p in (2,3,5,6):  # main
            pat = (0,4,8,11,12) if bar in (1,3) else (0,4,8,12)
            if p==6 and bar==3: pat=(0,3,4,8,10,12)
            kick_bar(p,bar,pat)
            bass_bar(p,bar,rsemi_bass,ghost=(p in (5,6)))
            arp_bar(p,bar,rsemi_arp,qual,'main')
            hats_bar(p,bar,'main')
            snare_bar(p,bar,v=.78,clap=.32)
            if bar in (0,2):
                stab_hit(p,bar,2,rsemi_stab,qual,.5); stab_hit(p,bar,10,rsemi_stab,qual,.44)
            else:
                stab_hit(p,bar,2,rsemi_stab,qual,.46)
        elif p==4:  # break
            if bar>=2: kick_bar(p,bar)
            bass_bar(p,bar,rsemi_bass)
            arp_bar(p,bar,rsemi_arp,qual,'8ths')
            hats_bar(p,bar,'break')
            stab_hit(p,bar,0,rsemi_stab,qual,.55); stab_hit(p,bar,8,rsemi_stab,qual,.5)
            if bar==3:
                for i,pos in enumerate(range(0,16)):
                    v = .22 + .5*i/15
                    C(p, 48+pos, SNRE, 61, INS['snare'], VB(v))
        elif p==7:  # outro
            kick_bar(p,bar); bass_bar(p,bar,rsemi_bass)
            arp_bar(p,bar,rsemi_arp,qual,'main')
            hats_bar(p,bar,'8ths')
            if bar in (0,2):
                stab_hit(p,bar,2,rsemi_stab,qual,.44); stab_hit(p,bar,10,rsemi_stab,qual,.40)
    # leads & echo
    lead_pat(p)
    if p in ECHO_PAT: echo_pat(p)

# FX events
C(3, 56, FX, 49, INS['fxdown'], VB(.5))
C(4, 52, FX, 49, INS['fxrise'], VB(.5))
C(6, 56, FX, 49, INS['fxdown'], VB(.42))
# crashes (open hat) at section starts
C(2, 0, HATS, 73, INS['ohat'], VB(.6))
C(5, 0, HATS, 73, INS['ohat'], VB(.6))

# ---------------- emit batch ----------------
batch = [{"name":"module_new","arguments":{"channels":8,"name":"keygen.exe // 0day"}},]
for ins,name,b64,vol,pan,ln in S:
    batch.append({"name":"sample_create_from_pcm","arguments":{"instrument":ins,"sample":0,"pcm":b64,"encoding":"int16","name":name}})
    batch.append({"name":"sample_set","arguments":{"instrument":ins,"sample":0,"name":name,"volume":vol,"panning":pan,"flags":0,"relative_note":0,"finetune":0}})
    batch.append({"name":"instrument_set","arguments":{"instrument":ins,"name":name}})
for (p,r,ch,note,ins,vol,fx,fxp) in cells:
    a = {"pattern":p,"row":r,"channel":ch}
    if note is not None: a["note"]=note
    if ins is not None: a["instrument"]=ins
    if vol is not None: a["volume"]=vol
    if fx is not None: a["effect"]=fx; a["effect_param"]=fxp
    batch.append({"name":"pattern_set_cell","arguments":a})
for pos in range(8):
    batch.append({"name":"order_set","arguments":{"position":pos,"pattern":pos}})
